D=[[int(x) for x in s] for s in ['444444444444444','944494499944494','444444444444494','944444444444444','444444444444494','444444444444494','944444444444494','944444444444444','944444444444444','444444444444494','444444444444494','949444444944494']]
for typ in ['row','col']:
 lines=D if typ=='row' else list(map(list,zip(*D)))
 for i,line in enumerate(lines):
  p=[j for j,x in enumerate(line) if x==9]
